// The notification title and body a phone shows are product copy, and product
// copy lives in the locale files. The dispatcher runs on Deno in a Supabase
// Edge Function and cannot read them at runtime, so they are generated into it
// — from the same fifteen files the app itself uses, never typed twice.
//
// `--check` fails the build when the generated file drifts from the locales,
// the same contract `build-site-languages.mjs` holds for the public site.
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const localeDir = 'src/i18n/locales';
const target = 'supabase/functions/dispatch-push/copy.ts';
// The database emits these; the locale files spell them the way the rest of
// the app does.
const KINDS = [
  ['new_match', 'newMatch'],
  ['new_message', 'newMessage'],
  ['moderation_status', 'moderationStatus'],
  ['safety_alert', 'safetyAlert'],
  ['product_notice', 'productNotice'],
];

const locales = readdirSync(localeDir).filter((name) => name.endsWith('.json')).map((name) => name.replace(/\.json$/, '')).sort();
const copy = {};
const missing = [];
for (const locale of locales) {
  const source = JSON.parse(readFileSync(join(localeDir, `${locale}.json`), 'utf8'));
  copy[locale] = {};
  for (const [dbKind, localeKind] of KINDS) {
    const entry = source.push?.[localeKind];
    if (!entry?.title || !entry?.body) { missing.push(`${locale}.${localeKind}`); continue; }
    copy[locale][dbKind] = { title: entry.title, body: entry.body };
  }
}
if (missing.length) {
  console.error(`Push copy is missing for: ${missing.join(', ')}`);
  process.exit(1);
}

const generated = `// Generated by \`npm run push:copy\` — do not edit by hand.
//
// The words a notification shows, per language, taken from src/i18n/locales.
// A language the recipient has not chosen, or one that is missing a line,
// falls back to English rather than showing nothing.
export type PushKind = ${KINDS.map(([dbKind]) => `"${dbKind}"`).join(' | ')};

export const PUSH_COPY: Record<string, Record<PushKind, { title: string; body: string }>> = ${JSON.stringify(copy, null, 2)};

export const FALLBACK_LOCALE = "en";

export function pushCopy(locale: string | null, kind: PushKind): { title: string; body: string } {
  const exact = locale ? PUSH_COPY[locale] : undefined;
  // "de-AT" should read German rather than English.
  const base = !exact && locale?.includes("-") ? PUSH_COPY[locale.split("-")[0]] : undefined;
  return (exact ?? base ?? PUSH_COPY[FALLBACK_LOCALE])[kind] ?? PUSH_COPY[FALLBACK_LOCALE][kind];
}
`;

if (process.argv.includes('--check')) {
  const current = readFileSync(target, 'utf8');
  if (current !== generated) {
    console.error(`${target} is out of date. Run \`npm run push:copy\`.`);
    process.exit(1);
  }
  console.log(`Push copy matches the locales for ${locales.length} languages.`);
  process.exit(0);
}

writeFileSync(target, generated);
console.log(`Wrote push copy for ${locales.length} languages to ${target}.`);
